default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Wdi\{9C5A40Da-B965-4Fc3-8781-88Dd50A6299D}' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('ScenarioExecutionEnabled', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]0)) {
    Write-Output 'Mismatch: HKLM:\Software\Policies\Microsoft\Windows\Wdi\{9C5A40Da-B965-4Fc3-8781-88Dd50A6299D} [ScenarioExecutionEnabled]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Wdi\{9C5A40Da-B965-4Fc3-8781-88Dd50A6299D}')) {
    New-Item -Path 'HKLM:\Software\Policies\Microsoft\Windows\Wdi\{9C5A40Da-B965-4Fc3-8781-88Dd50A6299D}' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\Software\Policies\Microsoft\Windows\Wdi\{9C5A40Da-B965-4Fc3-8781-88Dd50A6299D}' -Name 'ScenarioExecutionEnabled' -Value 0 -PropertyType DWord -Force | Out-Null
exit 0
